import{_ as i,o as t,c as a,al as s}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"MAVLink Message Signing","description":"","frontmatter":{},"headers":[],"relativePath":"uk/mavlink/message_signing.md","filePath":"uk/mavlink/message_signing.md"}'),n={name:"uk/mavlink/message_signing.md"};function o(r,e,l,d,g,c){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="mavlink-message-signing" tabindex="-1">MAVLink Message Signing <a class="header-anchor" href="#mavlink-message-signing" aria-label="Permalink to &quot;MAVLink Message Signing&quot;">​</a></h1><p><a href="https://mavlink.io/en/guide/message_signing.html" target="_blank" rel="noreferrer">MAVLink 2 message signing</a> allows PX4 to cryptographically verify that incoming MAVLink messages originate from a trusted source (authentication).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This mechanism does not <em>encrypt</em> the message payload.</p></div><h2 id="загальнии-огляд" tabindex="-1">Загальний огляд <a class="header-anchor" href="#загальнии-огляд" aria-label="Permalink to &quot;Загальний огляд&quot;">​</a></h2><p>When signing is enabled, PX4 appends a 13-byte <a href="https://mavlink.io/en/guide/message_signing.html#signature" target="_blank" rel="noreferrer">signature</a> to every outgoing MAVLink 2 message.</p><p>Incoming messages are checked against the shared secret key, and unsigned or incorrectly signed messages are rejected (with <a href="#unsigned-message-allowlist">exceptions for safety-critical messages</a>).</p><p>The signing implementation is built into the MAVLink module and is always available, with no special build flags required. The key is stored in an SD card:</p><ul><li><strong>No key on SD card</strong>: Signing is disabled. All messages are sent unsigned and all incoming messages are accepted.</li><li><strong>Valid key on SD card</strong>: Signing is active on <strong>all links</strong> (including USB). Outgoing messages are signed. Incoming messages must be signed (with <a href="#unsigned-message-allowlist">exceptions</a>).</li></ul><h2 id="enable-disable-signing" tabindex="-1">Enable/Disable Signing <a class="header-anchor" href="#enable-disable-signing" aria-label="Permalink to &quot;Enable/Disable Signing&quot;">​</a></h2><p>Signing is controlled using the standard MAVLink <a href="https://mavlink.io/en/messages/common.html#SETUP_SIGNING" target="_blank" rel="noreferrer">SETUP_SIGNING</a> message (as per the <a href="https://mavlink.io/en/guide/message_signing.html" target="_blank" rel="noreferrer">MAVLink signing specification</a>):</p><ul><li>To <strong>enable</strong> signing, send a <code>SETUP_SIGNING</code> message with a valid key on any link when no key is currently provisioned (see <a href="#key-provisioning">Key Provisioning</a>).</li><li>To <strong>disable</strong> signing via MAVLink, send a <code>SETUP_SIGNING</code> message with an all-zero key and timestamp. This message <strong>must be signed with the current active key</strong>. An unsigned blank-key message is rejected.</li><li>To <strong>change</strong> the signing key, send a <code>SETUP_SIGNING</code> message with the new key on any link. When signing is already active, the message must be signed with the current key.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Signing key changes (enable, disable, or rotate) are <strong>rejected while the vehicle is armed</strong>. The vehicle must be disarmed before signing configuration can be changed.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the signing key is lost, you can still disable signing if you have physical access to the vehicle. Either delete the key file (<code>/mavlink/mavlink-signing-key.bin</code>) from the SD card and reboot, or remove the SD card entirely.</p></div><h2 id="key-provisioning" tabindex="-1">Key Provisioning <a class="header-anchor" href="#key-provisioning" aria-label="Permalink to &quot;Key Provisioning&quot;">​</a></h2><p>The signing key is set by sending the MAVLink <a href="https://mavlink.io/en/messages/common.html#SETUP_SIGNING" target="_blank" rel="noreferrer">SETUP_SIGNING</a> message (ID 256) to PX4. This message contains:</p><ul><li>A 32-byte secret key</li><li>A 64-bit initial timestamp</li></ul><p>PX4 accepts <code>SETUP_SIGNING</code> on <strong>any link</strong> (USB, telemetry radio, network, and so on).</p><p>When signing is <strong>not active</strong> (no key provisioned), the first <code>SETUP_SIGNING</code> with a valid key enables signing. When signing is <strong>already active</strong>, key changes (including disabling) require that the <code>SETUP_SIGNING</code> message is signed with the current key.</p><p>Note that <code>SETUP_SIGNING</code> is rejected while the vehicle is armed (disarm before provisioning or changing keys). As per the MAVLink specification, <code>SETUP_SIGNING</code> is never forwarded to other links.</p><h2 id="key-storage" tabindex="-1">Key Storage <a class="header-anchor" href="#key-storage" aria-label="Permalink to &quot;Key Storage&quot;">​</a></h2><p>The secret key and timestamp are stored on the SD card at:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/mavlink/mavlink-signing-key.bin</span></span></code></pre></div><p>The file is a 40-byte binary file:</p><table tabindex="0"><thead><tr><th>Offset</th><th>Розмір</th><th>Content</th></tr></thead><tbody><tr><td>0</td><td>32 bytes</td><td>Secret key</td></tr><tr><td>32</td><td>8 bytes</td><td>Timestamp (<code>uint64_t</code>, little-endian)</td></tr></tbody></table><p>The file is created with mode <code>0600</code> (owner read/write only), and the containing <code>/mavlink/</code> directory is created with mode <code>0700</code> (owner only).</p><p>On startup, PX4 reads the key from this file. If the file exists and contains a non-zero key or timestamp, signing is activated automatically.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The timestamp in the file is set when <code>SETUP_SIGNING</code> is received. A graceful shutdown also writes the current timestamp back, but in practice most vehicles are powered off by pulling the battery, so the on-disk timestamp will typically remain at the value from the last key provisioning.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Storage of the key on the SD card means that signing can be disabled by removing the card. Note that this requires physical access to the vehicle.</p></div><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><h3 id="initialization" tabindex="-1">Initialization <a class="header-anchor" href="#initialization" aria-label="Permalink to &quot;Initialization&quot;">​</a></h3><ol><li>The MAVLink module calls <code>MavlinkSignControl::start()</code> during startup.</li><li>The <code>/mavlink/</code> directory is created if it doesn&#39;t exist.</li><li>The <code>mavlink-signing-key.bin</code> file is opened if it exists.</li><li>If a valid key is found (non-zero key or timestamp), signing is activated: the signing struct is wired into the MAVLink library and outgoing messages are signed.</li><li>If no valid key is found, the signing struct is left disconnected, and the MAVLink library operates with zero signing overhead.</li></ol><h3 id="outgoing-messages" tabindex="-1">Outgoing Messages <a class="header-anchor" href="#outgoing-messages" aria-label="Permalink to &quot;Outgoing Messages&quot;">​</a></h3><p>When signing is active (valid key present), the <code>MAVLINK_SIGNING_FLAG_SIGN_OUTGOING</code> flag is set, which causes the MAVLink library to automatically append a <a href="https://mavlink.io/en/guide/message_signing.html#signature" target="_blank" rel="noreferrer">SHA-256 based signature</a> to every outgoing MAVLink 2 message.</p><p>When no key is present, signing is completely bypassed with no CPU or bandwidth overhead.</p><h3 id="incoming-messages" tabindex="-1">Incoming Messages <a class="header-anchor" href="#incoming-messages" aria-label="Permalink to &quot;Incoming Messages&quot;">​</a></h3><p>For each incoming message, the MAVLink library checks whether a valid signature is present. If the message is unsigned or has an invalid signature, the library calls the <code>accept_unsigned</code> callback, which decides whether to accept or reject the message based on:</p><ol><li><strong>Signing not active</strong>: If no key has been loaded, all messages are accepted.</li><li><strong>Allowlisted message</strong>: Certain <a href="#unsigned-message-allowlist">safety-critical messages</a> are always accepted.</li></ol><h2 id="unsigned-message-allowlist" tabindex="-1">Unsigned Message Allowlist <a class="header-anchor" href="#unsigned-message-allowlist" aria-label="Permalink to &quot;Unsigned Message Allowlist&quot;">​</a></h2><p>The following messages are <strong>always</strong> accepted unsigned, regardless of the signing state. These are safety-critical messages that may originate from systems that don&#39;t support signing:</p><table tabindex="0"><thead><tr><th>Повідомлення</th><th>ID</th><th>Reason</th></tr></thead><tbody><tr><td><a href="https://mavlink.io/en/messages/common.html#HEARTBEAT" target="_blank" rel="noreferrer">HEARTBEAT</a></td><td>0</td><td>System discovery and liveness detection</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#RADIO_STATUS" target="_blank" rel="noreferrer">RADIO_STATUS</a></td><td>109</td><td>Radio link status from SiK radios and other radio modems</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#ADSB_VEHICLE" target="_blank" rel="noreferrer">ADSB_VEHICLE</a></td><td>246</td><td>ADS-B traffic information for collision avoidance</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#COLLISION" target="_blank" rel="noreferrer">COLLISION</a></td><td>247</td><td>Collision threat warnings</td></tr></tbody></table><h2 id="security-considerations" tabindex="-1">Security Considerations <a class="header-anchor" href="#security-considerations" aria-label="Permalink to &quot;Security Considerations&quot;">​</a></h2><h3 id="signing-is-enforced-on-all-links" tabindex="-1">Signing is enforced on all links <a class="header-anchor" href="#signing-is-enforced-on-all-links" aria-label="Permalink to &quot;Signing is enforced on all links&quot;">​</a></h3><p>When signing is active, <strong>all links require signed messages</strong>. This means:</p><ul><li>An attacker cannot send unsigned commands on any link.</li><li>Changing or disabling the key requires sending a <code>SETUP_SIGNING</code> message <strong>signed with the current key</strong>.</li><li>Signing can be disabled via MAVLink by sending a signed <code>SETUP_SIGNING</code> with an all-zero key.</li></ul><h3 id="armed-guard" tabindex="-1">Armed guard <a class="header-anchor" href="#armed-guard" aria-label="Permalink to &quot;Armed guard&quot;">​</a></h3><p><code>SETUP_SIGNING</code> is rejected while the vehicle is armed. This prevents the signing configuration from being changed during flight, whether by accident or by an attacker who has obtained the key.</p><h3 id="lost-key-recovery" tabindex="-1">Lost key recovery <a class="header-anchor" href="#lost-key-recovery" aria-label="Permalink to &quot;Lost key recovery&quot;">​</a></h3><p>If the signing key is lost on the GCS side and no device has the current key:</p><ul><li><strong>Remove the SD card</strong> and delete <code>/mavlink/mavlink-signing-key.bin</code>, then reboot.</li><li><strong>Reflash via SWD/JTAG</strong> if the SD card is not accessible.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>There is no software-only recovery path for a lost key. This is intentional: any MAVLink-based recovery mechanism would also be available to an attacker. Physical access to the SD card or debug port is required.</p></div><h3 id="other-considerations" tabindex="-1">Other considerations <a class="header-anchor" href="#other-considerations" aria-label="Permalink to &quot;Other considerations&quot;">​</a></h3><ul><li><strong>Initial key provisioning</strong>: When no key is provisioned, <code>SETUP_SIGNING</code> is accepted unsigned on any link. Once a key is active, subsequent changes require a signed message. Provision the initial key over a trusted connection, such as USB.</li><li><strong>Key not exposed via parameters</strong>: The secret key is stored in a separate file on the SD card, not as a MAVLink parameter, so it cannot be read back through the parameter protocol.</li><li><strong>SD card access</strong>: Anyone with physical access to the SD card can read or modify the <code>mavlink-signing-key.bin</code> file, or remove the card entirely to disable signing. Ensure physical security of the vehicle if signing is used as a security control.</li><li><strong>Replay protection</strong>: The MAVLink signing protocol includes a timestamp that prevents replay attacks. The on-disk timestamp is updated when a new key is provisioned via <code>SETUP_SIGNING</code>. A graceful shutdown also persists the current timestamp, but since most vehicles are powered off by pulling the battery, the on-disk timestamp will typically remain at the value from the last key provisioning on reboot.</li><li><strong>No encryption</strong>: Message signing provides <strong>authentication and integrity only</strong>. Messages are still sent in plaintext. An eavesdropper can read all message contents (telemetry, commands, parameters, missions) but cannot forge or modify them without the key.</li><li><strong>Allowlisted messages bypass signing</strong>: A small set of <a href="#unsigned-message-allowlist">safety-critical messages</a> are always accepted unsigned. An attacker can spoof these specific messages (e.g. fake <code>ADSB_VEHICLE</code> traffic) even when signing is active.</li></ul><h3 id="what-signing-does-not-protect-against" tabindex="-1">What signing does NOT protect against <a class="header-anchor" href="#what-signing-does-not-protect-against" aria-label="Permalink to &quot;What signing does NOT protect against&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Attack</th><th>Why</th></tr></thead><tbody><tr><td>Eavesdropping</td><td>Messages are not encrypted</td></tr><tr><td>SD card extraction</td><td>Key file is readable by anyone with physical access</td></tr><tr><td>Spoofed <code>HEARTBEAT</code>/<code>RADIO_STATUS</code>/<code>ADSB</code>/<code>COLLISION</code></td><td>These are allowlisted unsigned</td></tr><tr><td>Lost key without SD card access</td><td>Requires SWD reflash</td></tr><tr><td>Key rotation</td><td>No automatic mechanism; manual re-provisioning required</td></tr><tr><td>In-flight key changes</td><td><code>SETUP_SIGNING</code> rejected while armed</td></tr></tbody></table>',54)])])}const p=i(n,[["render",o]]);export{m as __pageData,p as default};
